package br.com.brindespro.order;
import br.com.brindespro.quote.Quote;import jakarta.persistence.*;import java.time.OffsetDateTime;
@Entity @Table(name="order_status_history") public class OrderStatusHistory { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id;@ManyToOne(optional=false) @JoinColumn(name="quote_id") public Quote quote;@Column(nullable=false) public String status;@Column(length=1000) public String note="";@Column(name="visible_to_customer",nullable=false) public boolean visibleToCustomer=true;@Column(name="changed_by") public String changedBy="";@Column(name="created_at",nullable=false) public OffsetDateTime createdAt=OffsetDateTime.now();protected OrderStatusHistory(){}public OrderStatusHistory(Quote quote,String status,String note,boolean visible,String by){this.quote=quote;this.status=status;this.note=note==null?"":note;this.visibleToCustomer=visible;this.changedBy=by==null?"":by;} }
